// === Tab: mySketch.js ===
let Shader, palette;
let legends = [];
let sliders = [];
var p1, p2, fscale, xpan, ypan; // parameters to shader
var isDirty = true; // need to draw the image?

function preload() {
	Shader = getShader(this._renderer);
	palette = loadImage('https://openprocessing.org/sketch/1593100/files/tiger.png') 
}

// ----------------------------------------------------

let sliderY = 10

function sliderChanged() {
	isDirty = true
}

function addSlider() {
	legends.push(createInput(" "));
	let q = legends[legends.length - 1]
	q.size(120)
	q.style('font-size', '16px')
	q.style('background-color', color(0))
	q.style('color', color(255))
	q.position(10, sliderY)
	q.input(sliderChanged)

	sliders.push(createSlider(0, 1000, 500))
	sliders[sliders.length - 1].style('width', '380px');
	sliders[sliders.length - 1].position(140, sliderY)
	sliders[sliders.length - 1].input(sliderChanged)
	sliderY += 30
}

function sliderScaledValue(index, min, range) {
	return min + range * (sliders[index].value() - 500) * 0.001
}

// ----------------------------------------------------

function setup() {
	createCanvas(1000, 1000, WEBGL);
	for (let i = 0; i < 5; ++i) addSlider()
}

function keyPressed() {
	//print(key,keyCode)
	if(keyCode == 224) close();  // shift+command+return stops program as usual
}

function draw() {
	if (!isDirty) return // only draw when changes are made
	isDirty = false

	p1 = sliderScaledValue(0, 0.0027, 0.03) // array index,  default value, range of slider effect 
	p2 = sliderScaledValue(1, 0.2786, 0.01)
	fscale = sliderScaledValue(2, 0.3, 10.0)
	xpan = sliderScaledValue(3, 0.0, 10.0)
	ypan = sliderScaledValue(4, 0.0, 10.0)

	legends[0].value("P1: " + p1.toFixed(4))
	legends[1].value("P2: " + p2.toFixed(4))
	legends[2].value("Scale: " + fscale.toFixed(4))
	legends[3].value("X pan: " + xpan.toFixed(4))
	legends[4].value("Y pan: " + ypan.toFixed(4))

	shader(Shader)
	Shader.setUniform('pal', palette);
	Shader.setUniform('p1', p1)
	Shader.setUniform('p2', p2)
	Shader.setUniform('fscale', fscale)
	Shader.setUniform('xpan', xpan)
	Shader.setUniform('ypan', ypan)
	rect(0, 0, width, height)
}

// ----------------------------------------------------

function getShader(_renderer) {
	const frag = ` 
		precision highp float;
 		varying vec2 vTexCoord;		// pixel coordinate as 0..1
 		uniform float p1,p2,fscale,xpan,ypan;
		uniform sampler2D pal;

		void main() {
 			float oldx,x = (vTexCoord.x - 0.5) * fscale + xpan;
 			float y = (vTexCoord.y - 0.5) * fscale + ypan;
			vec2 color = vTexCoord;
			color.y = 1.0 - color.y;
			float factor = 0.01;

			 for(int i=0;i < 25; ++i) {
					 if(x*x + y*y > 20.0) break;
					 oldx = x;
					 x = x * y * 2.0 + p1;
			 		 y = sin(y*y - oldx*oldx) + p2;
					 color.x += x * factor;
					 color.y += y * factor;
					 factor *= 0.95;
			 }

			gl_FragColor = texture2D(pal,color); 
		}
	`;

	const vert = `
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`;

	return createShader(vert, frag);
}

